 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The three adjacent top-row markers seed three colored rays.
    seeds = [(0, c, grid[0][c]) for c in range(w) if grid[0][c] != 0]
    if len(seeds) != 3:
        return out
    for i, (r, c, color) in enumerate(seeds):
        matches = [(rr, cc) for rr in range(h) for cc in range(w)
                   if (rr, cc) != (r, c) and grid[rr][cc] == color]
        if matches:
            # Route downward in the seed's column, then horizontally to its mate.
            rr, cc = matches[0]
            for y in range(min(r, rr), max(r, rr) + 1):
                out[y][c] = color
            for x in range(min(c, cc), max(c, cc) + 1):
                out[rr][x] = color
        elif i == 1:
            for y in range(r, h):
                out[y][c] = color
    return out
